import type {
  JapaneseActivity, JapaneseActivityBase, JapaneseBuildActivity, JapaneseChoice,
  JapaneseChoiceActivity, JapaneseCourseSource, JapaneseCourseUnit, JapaneseLocalized,
  JapaneseMatchActivity, JapanesePhrase, JapaneseReadingActivity, JapaneseRoleplayTurn,
} from "./japaneseCourseTypes";

// All scenes, prompts, feedback and translations below are original course content.
// Source links inform the approach; no textbook activities or recordings are copied.
const l = (fr: string, en: string, es: string): JapaneseLocalized => ({ fr, en, es });
const p = (ja: string, kana: string, romaji: string, fr: string, en: string, es: string): JapanesePhrase =>
  ({ ja, kana, romaji, meaning: l(fr, en, es) });
const d = (speaker: JapaneseLocalized, phrase: JapanesePhrase) => ({ ...phrase, speaker });
const learner = l("Toi", "You", "Tú");
const aya = l("Aya, camarade de cours", "Aya, classmate", "Aya, compañera de clase");
const staff = l("L’équipe d’accueil", "Welcome desk staff", "Personal de recepción");
const clerk = l("La personne au comptoir", "Counter staff", "La persona del mostrador");
const v = (unit: number, phrases: JapanesePhrase[]) => phrases.map((phrase, i) => ({
  ...phrase, id: `jp-${unit}-vocab-${i + 1}`,
}));
const a = (id: string, title: JapaneseLocalized, prompt: JapaneseLocalized, hint: JapaneseLocalized,
  explanation: JapaneseLocalized, skill: JapaneseActivityBase["skill"]): JapaneseActivityBase =>
  ({ id, title, prompt, hint, explanation, skill });
const option = (id: string, phrase: JapanesePhrase, feedback: JapaneseLocalized): JapaneseChoice =>
  ({ id, ja: phrase.ja, kana: phrase.kana, romaji: phrase.romaji, feedback });
const labelOption = (id: string, label: JapaneseLocalized, feedback: JapaneseLocalized): JapaneseChoice =>
  ({ id, label, feedback });
const j = (id: string, ja: string, kana: string, romaji: string, fr: string, en: string, es: string): JapaneseChoice =>
  ({ id, ja, kana, romaji, feedback: l(fr, en, es) });
const choice = (base: JapaneseActivityBase, choices: JapaneseChoice[], answerId: string,
  extra: { kind?: "choice" | "listening" | "culture"; stimulus?: JapanesePhrase; sourceIds?: string[] } = {}): JapaneseChoiceActivity =>
  ({ ...base, kind: "choice", choices, answerId, ...extra });
const build = (base: JapaneseActivityBase, ordered: string[], phrase: JapanesePhrase): JapaneseBuildActivity => {
  const tokens = ordered.map((text, i) => ({ id: `${base.id}-token-${i + 1}`, text }));
  // A fixed rotation is reproducible, starts unsolved and preserves stable token IDs.
  return { ...base, kind: "build", tokens: [...tokens.slice(2), ...tokens.slice(0, 2)], answerOrder: tokens.map(t => t.id), phrase };
};
const reading = (base: JapaneseActivityBase, stimulus: string, answer: string, accepted: string[] = [answer]): JapaneseReadingActivity =>
  ({ ...base, kind: "reading", stimulus, answer, accepted, acceptsRomaji: false });
const match = (base: JapaneseActivityBase, phrases: JapanesePhrase[]): JapaneseMatchActivity =>
  ({ ...base, kind: "match", pairs: phrases.map((phrase, i) => ({ id: `${base.id}-pair-${i + 1}`, phrase })) });
const turn = (id: string, speaker: JapaneseLocalized, line: JapanesePhrase, goal: JapaneseLocalized,
  hint: JapaneseLocalized, choices: JapaneseChoice[], answerId: string): JapaneseRoleplayTurn =>
  ({ id, speaker, line, goal, hint, choices, answerId });

